export default function cameraWorkflow(fixture) {
  const trace = [];
  function allocate(size) {
    return new Float32Array(size);
  }
  function store(out, index, value, stage) {
    out[index] = value;
    trace.push({event:"store", stage, index, input:value, stored:out[index]});
  }
  function identity(out, stage) {
    store(out, 0, 1, stage);
    store(out, 1, 0, stage);
    store(out, 2, 0, stage);
    store(out, 3, 0, stage);
    store(out, 4, 0, stage);
    store(out, 5, 1, stage);
    store(out, 6, 0, stage);
    store(out, 7, 0, stage);
    store(out, 8, 0, stage);
    store(out, 9, 0, stage);
    store(out, 10, 1, stage);
    store(out, 11, 0, stage);
    store(out, 12, 0, stage);
    store(out, 13, 0, stage);
    store(out, 14, 0, stage);
    store(out, 15, 1, stage);
    return out;
  }

  function lookAt(out, eye, center, up, stage) {
    let x0, x1, x2, y0, y1, y2, z0, z1, z2, lengthValue;
    let eyex = eye[0];
    let eyey = eye[1];
    let eyez = eye[2];
    let upx = up[0];
    let upy = up[1];
    let upz = up[2];
    let centerx = center[0];
    let centery = center[1];
    let centerz = center[2];

    if (
      Math.abs(eyex - centerx) < 0.000001 &&
      Math.abs(eyey - centery) < 0.000001 &&
      Math.abs(eyez - centerz) < 0.000001
    ) {
      trace.push({event:"lookAt:identity"});
      return identity(out, stage);
    }

    trace.push({event:"lookAt:ordinary"});
    z0 = eyex - centerx;
    z1 = eyey - centery;
    z2 = eyez - centerz;

    lengthValue = 1 / Math.sqrt(z0 * z0 + z1 * z1 + z2 * z2);
    z0 *= lengthValue;
    z1 *= lengthValue;
    z2 *= lengthValue;

    x0 = upy * z2 - upz * z1;
    x1 = upz * z0 - upx * z2;
    x2 = upx * z1 - upy * z0;
    lengthValue = Math.sqrt(x0 * x0 + x1 * x1 + x2 * x2);
    trace.push({event:lengthValue ? "lookAt:right-normalized" : "lookAt:right-zero"});
    if (!lengthValue) {
      x0 = 0;
      x1 = 0;
      x2 = 0;
    } else {
      lengthValue = 1 / lengthValue;
      x0 *= lengthValue;
      x1 *= lengthValue;
      x2 *= lengthValue;
    }

    y0 = z1 * x2 - z2 * x1;
    y1 = z2 * x0 - z0 * x2;
    y2 = z0 * x1 - z1 * x0;

    lengthValue = Math.sqrt(y0 * y0 + y1 * y1 + y2 * y2);
    trace.push({event:lengthValue ? "lookAt:up-normalized" : "lookAt:up-zero"});
    if (!lengthValue) {
      y0 = 0;
      y1 = 0;
      y2 = 0;
    } else {
      lengthValue = 1 / lengthValue;
      y0 *= lengthValue;
      y1 *= lengthValue;
      y2 *= lengthValue;
    }

    store(out, 0, x0, stage);
    store(out, 1, y0, stage);
    store(out, 2, z0, stage);
    store(out, 3, 0, stage);
    store(out, 4, x1, stage);
    store(out, 5, y1, stage);
    store(out, 6, z1, stage);
    store(out, 7, 0, stage);
    store(out, 8, x2, stage);
    store(out, 9, y2, stage);
    store(out, 10, z2, stage);
    store(out, 11, 0, stage);
    store(out, 12, -(x0 * eyex + x1 * eyey + x2 * eyez), stage);
    store(out, 13, -(y0 * eyex + y1 * eyey + y2 * eyez), stage);
    store(out, 14, -(z0 * eyex + z1 * eyey + z2 * eyez), stage);
    store(out, 15, 1, stage);

    return out;
  }

  function perspectiveNO(out, fovy, aspect, near, far, stage) {
    const focalScale = 1.0 / Math.tan(fovy / 2);
    store(out, 0, focalScale / aspect, stage);
    store(out, 1, 0, stage);
    store(out, 2, 0, stage);
    store(out, 3, 0, stage);
    store(out, 4, 0, stage);
    store(out, 5, focalScale, stage);
    store(out, 6, 0, stage);
    store(out, 7, 0, stage);
    store(out, 8, 0, stage);
    store(out, 9, 0, stage);
    store(out, 11, -1, stage);
    store(out, 12, 0, stage);
    store(out, 13, 0, stage);
    store(out, 15, 0, stage);
    if (far != null && far !== Infinity) {
      trace.push({event:"perspective:finite-far"});
      const inverseDepthRange = 1 / (near - far);
      store(out, 10, (far + near) * inverseDepthRange, stage);
      store(out, 14, 2 * far * near * inverseDepthRange, stage);
    } else {
      store(out, 10, -1, stage);
      store(out, 14, -2 * near, stage);
    }
    return out;
  }

  function fromValues(coordX, coordY, coordZ, stage) {
    let out = allocate(3);
    store(out, 0, coordX, stage);
    store(out, 1, coordY, stage);
    store(out, 2, coordZ, stage);
    return out;
  }

  function transformMat4(out, vector, matrix, stage) {
    let coordX = vector[0],
      coordY = vector[1],
      coordZ = vector[2];
    let homogeneousW = matrix[3] * coordX + matrix[7] * coordY + matrix[11] * coordZ + matrix[15];
    trace.push({event:homogeneousW ? "transform:nonzero-w" : "transform:zero-w-fallback",stage,homogeneousW});
    homogeneousW = homogeneousW || 1.0;
    store(out, 0, (matrix[0] * coordX + matrix[4] * coordY + matrix[8] * coordZ + matrix[12]) / homogeneousW, stage);
    store(out, 1, (matrix[1] * coordX + matrix[5] * coordY + matrix[9] * coordZ + matrix[13]) / homogeneousW, stage);
    store(out, 2, (matrix[2] * coordX + matrix[6] * coordY + matrix[10] * coordZ + matrix[14]) / homogeneousW, stage);
    return out;
  }

  function floatWord(value) {
    if (value === 0) return Object.is(value, -0) ? 2147483648 : 0;
    const signBit = value < 0 ? 2147483648 : 0;
    const magnitude = Math.abs(value);
    const exponent = Math.floor(Math.log2(magnitude));
    const fraction = Math.round((magnitude / Math.pow(2, exponent) - 1) * 8388608);
    return signBit + (exponent + 127) * 8388608 + fraction;
  }
  function pack(buffer) {
    const values = [];
    const words = [];
    for (let index = 0; index < buffer.length; index++) {
      values.push(buffer[index]);
      words.push(floatWord(buffer[index]));
    }
    return {values, words};
  }
  const samples = [];
  try {
    const eye = fromValues(fixture.eye[0], fixture.eye[1], fixture.eye[2], "eye");
    const center = fromValues(fixture.center[0], fixture.center[1], fixture.center[2], "center");
    const up = fromValues(fixture.up[0], fixture.up[1], fixture.up[2], "up");
    const view = lookAt(allocate(16), eye, center, up, "view");
    const projection = perspectiveNO(allocate(16), fixture.fovDegrees * Math.PI / 180, fixture.aspect, fixture.near, fixture.far, "projection");
    for (let index = 0; index < fixture.points.length; index++) {
      const input = fixture.points[index];
      const point = fromValues(input[0], input[1], input[2], "point:" + index);
      const camera = transformMat4(allocate(3), point, view, "camera:" + index);
      const ndc = transformMat4(allocate(3), camera, projection, "ndc:" + index);
      const screen = [(ndc[0] + 1) * 0.5 * fixture.viewport[0], (1 - ndc[1]) * 0.5 * fixture.viewport[1], (ndc[2] + 1) * 0.5];
      samples.push({point:pack(point), camera:pack(camera), ndc:pack(ndc), screen});
    }
    return {ok:true, semantic:{eye:pack(eye), center:pack(center), up:pack(up), view:pack(view), projection:pack(projection), samples}, trace};
  } catch (error) {
    return {ok:false, error:{name:error.name, message:error.message}, partial:{samples}, trace};
  }
};
